operation.insert:
// #3696: the record certifies content up to line-ending normalization
// (digestOrAbsent), but it stores the operation as written. A record made on a
// CRLF checkout carries a CRLF anchor; re-run against an LF base read out of
// git, that anchor occurs zero times and an honest record reads as
// RERUN_FAILED. The re-run therefore sees base files and operation text in one
// convention. The derivation hash is still computed from the stored operation
// and LF-normalized digests, so normalizing here cannot change what matches.
function lineEndingNeutral(value) {
  if (typeof value === 'string') return value.replace(/\r\n/gu, '\n');
  if (Array.isArray(value)) return value.map(lineEndingNeutral);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, inner]) => [key, lineEndingNeutral(inner)]));
  }
  return value;
}

function runLineEndingNeutral(task) {
  return runTask({ ...task, operation: lineEndingNeutral(task.operation), files: lineEndingNeutral(task.files) });
}
